const SHORT_ALPHABET="0123456789ABCDEFGHJKMNPQRSTVWXYZ";const normalizeShort=s=>String(s||"").toUpperCase().replace(/[\s-]/g,"").replace(/O/g,"0").replace(/[IL]/g,"1").replace(/U/g,"V");const pairingBy=(raw,flow)=>{const v=String(raw||"");return db.prepare("SELECT * FROM pairings WHERE id_hash=? AND flow=?").get(hash(v),flow)||db.prepare("SELECT * FROM pairings WHERE short_code_hash=? AND flow=?").get(hash(normalizeShort(v)),flow);};
function pairingState(p){if(!p)return "missing";if(Date.parse(p.expires_at)<Date.now()&& !["completed","denied","expired"].includes(p.state)){db.prepare("UPDATE pairings SET state='expired' WHERE id_hash=?").run(p.id_hash);return "expired";}return p.state;}
function lanBase(req){if(process.env.PEO_YAME_PUBLIC_URL)return process.env.PEO_YAME_PUBLIC_URL.replace(/\/$/,"");if(process.env.PEO_YAME_LAN_HOST)return "http://"+process.env.PEO_YAME_LAN_HOST+":"+String(process.env.PORT||3000);const host=req.hostname||"127.0.0.1";if(host!=="localhost"&&!host.startsWith("127."))return req.protocol+"://"+req.get("host");for(const values of Object.values(os.networkInterfaces()))for(const x of values||[])if(x.family==="IPv4"&&!x.internal&&/^10\.|^192\.168\.|^172\.(1[6-9]|2[0-9]|3[01])\./.test(x.address))return "http://"+x.address+":"+String(process.env.PORT||3000);return req.protocol+"://"+req.get("host");}
function pairingCreate(flow,fields){const raw=crypto.randomBytes(16).toString("base64url"),shortCode=Array.from(crypto.randomBytes(8),b=>SHORT_ALPHABET[b%32]).join(""),stamp=now(),expires=new Date(Date.now()+90000).toISOString();db.prepare("INSERT INTO pairings(id_hash,flow,owner_user_id,owner_session_hash,verifier_hash,state,match_code,created_at,expires_at,short_code_hash) VALUES(?,?,?,?,?,'pending',?,?,?,?)").run(hash(raw),flow,fields.userId||null,fields.sessionHash||null,fields.verifierHash||null,String(crypto.randomInt(10,100)),stamp,expires,hash(normalizeShort(shortCode)));return {raw,shortCode,expiresAt:expires};}
const attemptPairing=(p,code)=>{if(!safeEq(p.match_code,String(code||""))){db.prepare("UPDATE pairings SET attempts=attempts+1,state=CASE WHEN attempts+1>=3 THEN 'denied' ELSE state END WHERE id_hash=? AND state='scanned'").run(p.id_hash);const fresh=db.prepare("SELECT attempts,state FROM pairings WHERE id_hash=?").get(p.id_hash),attempts=fresh?.attempts??p.attempts+1;return {ok:false,attemptsLeft:Math.max(0,3-attempts)};}return {ok:true};};
async function phoneQrResponse(req,res,p){const base=lanBase(req),payload=JSON.stringify({baseUrl:base,codeId:p.raw,flow:"phone"});res.json({codeId:p.raw,shortCode:p.shortCode,expiresAt:p.expiresAt,backendAddress:base,payload,qrDataUrl:await QRCode.toDataURL(payload,{errorCorrectionLevel:"M",margin:4,width:220})});}
app.post("/api/qr/phone/create",requireUser,async(req,res)=>{if(!rateLimit("qrphone:"+req.user.id,10,60000)||!rateLimit("reauth:"+req.user.id+":"+req.ip,5,60000))return tooMany(req,res);if(!requireReauthentication(req,res))return;const token=req.get("authorization")?.replace(/^Bearer /,"")||cookieValue(req,"py_session");const p=pairingCreate("phone",{userId:req.user.id,sessionHash:hash(token||"")});await phoneQrResponse(req,res,p);});
app.post("/api/qr/phone/renew",requireUser,async(req,res)=>{if(!rateLimit("qrphone:"+req.user.id,10,60000))return tooMany(req,res);const old=pairingBy(req.body?.codeId,"phone");if(!old||old.owner_user_id!==req.user.id||(old.owner_session_hash!==req.user.token_hash&&!req.user.totp_verified)||old.state==="completed")return res.status(404).json({error:"Phone request is no longer available."});db.prepare("UPDATE pairings SET state='expired' WHERE id_hash=? AND state IN ('pending','scanned','approved')").run(old.id_hash);const p=pairingCreate("phone",{userId:req.user.id,sessionHash:old.owner_session_hash});await phoneQrResponse(req,res,p);});
app.post("/api/qr/phone/cancel",requireUser,(req,res)=>{const p=pairingBy(req.body?.codeId,"phone");if(!p||p.owner_user_id!==req.user.id||(p.owner_session_hash!==req.user.token_hash&&!req.user.totp_verified))return res.status(404).json({error:"Phone request is no longer available."});if(["pending","scanned","approved"].includes(p.state))db.prepare("UPDATE pairings SET state='expired' WHERE id_hash=? AND state IN ('pending','scanned','approved')").run(p.id_hash);res.json({ok:true});});
app.post("/api/qr/phone/claim",(req,res)=>{if(!rateLimit("qrclaim:"+req.ip,20,60000))return tooMany(req,res);const p=pairingBy(req.body?.codeId,"phone");if(!p||pairingState(p)!=="pending")return res.status(410).json({error:p?.state==="expired"?"This code expired. Get a new one.":"This code was already used."});if(!/^[a-f0-9]{64}$/i.test(String(req.body?.verifierHash||"")))return res.status(400).json({error:"Phone verifier is invalid."});const result=db.prepare("UPDATE pairings SET state='scanned',verifier_hash=?,device_name=?,app_version=?,address=? WHERE id_hash=? AND state='pending'").run(req.body.verifierHash,String(req.body.name||"Phone").slice(0,80),String(req.body.version||"unknown").slice(0,40),req.ip,p.id_hash);if(!result.changes)return res.status(409).json({error:"This code was already used."});res.json({state:"scanned",matchCode:p.match_code,expiresAt:p.expires_at});});
app.post("/api/qr/phone/withdraw",(req,res)=>{const p=pairingBy(req.body?.codeId,"phone"),verifier=String(req.body?.verifier||"");if(!p||!verifier||!safeEq(hash(verifier),p.verifier_hash))return res.status(401).json({error:"Phone verifier did not match."});if(pairingState(p)==="scanned")db.prepare("UPDATE pairings SET state='cancelled' WHERE id_hash=? AND state='scanned'").run(p.id_hash);const current=db.prepare("SELECT * FROM pairings WHERE id_hash=?").get(p.id_hash);res.json({ok:true,state:pairingState(current)});});
app.get("/api/qr/phone/status",(req,res)=>{const p=pairingBy(req.query.codeId,"phone"),v=String(req.query.verifier||"");if(!p)return res.status(404).json({error:"Pairing code not found."});if(!v||!safeEq(hash(v),p.verifier_hash))return res.status(401).json({error:"Phone verifier did not match."});const state=pairingState(p);res.json({state,expiresAt:p.expires_at,message:state==="denied"?"This request was denied.":undefined});});
app.get("/api/qr/phone/owner-status",requireUser,(req,res)=>{const p=pairingBy(req.query.codeId,"phone");if(!p||p.owner_user_id!==req.user.id||(p.owner_session_hash!==req.user.token_hash&&!req.user.totp_verified))return res.status(404).json({error:"Phone request is no longer available."});res.json({state:pairingState(p),deviceName:p.device_name,appVersion:p.app_version,address:p.address,createdAt:p.created_at,expiresAt:p.expires_at});});
app.post("/api/qr/phone/approve",requireUser,(req,res)=>{if(req.user.totp_enabled&&!req.user.totp_verified)return res.status(403).json({error:"Re-authenticate with your authenticator code before approving.",totpRequired:true});const p=pairingBy(req.body?.codeId,"phone");if(!p||pairingState(p)!=="scanned"||p.owner_user_id!==req.user.id||(p.owner_session_hash!==req.user.token_hash&&!req.user.totp_verified))return res.status(404).json({error:"Phone request is no longer available."});const check=attemptPairing(p,req.body?.matchCode);if(!check.ok)return res.status(401).json({error:check.attemptsLeft?("That number did not match. "+check.attemptsLeft+" tries left."):"Too many tries. Start again.",attemptsLeft:check.attemptsLeft});const changed=db.prepare("UPDATE pairings SET state='approved',totp_verified=? WHERE id_hash=? AND state='scanned'").run(req.user.totp_verified?1:0,p.id_hash);if(!changed.changes)return res.status(409).json({error:"This request was already handled."});recordSecurityEvent(req.user.id,"phone_qr_approved");res.json({ok:true,message:"Phone approved."});});
app.post("/api/qr/phone/deny",requireUser,(req,res)=>{const p=pairingBy(req.body?.codeId,"phone");if(!p||p.owner_user_id!==req.user.id||(p.owner_session_hash!==req.user.token_hash&&!req.user.totp_verified))return res.status(404).json({error:"Phone request is no longer available."});db.prepare("UPDATE pairings SET state='denied' WHERE id_hash=? AND state='scanned'").run(p.id_hash);res.json({ok:true});});
app.post("/api/qr/phone/redeem",(req,res)=>{if(!rateLimit("redeem:"+req.ip,10,60000))return tooMany(req,res);const p=pairingBy(req.body?.codeId,"phone");if(!p||pairingState(p)!=="approved"||!req.body?.verifier||!safeEq(hash(req.body.verifier),p.verifier_hash))return res.status(401).json({error:"Phone approval is not available."});const u=db.prepare("SELECT * FROM users WHERE id=?").get(p.owner_user_id);if(!u)return res.status(401).json({error:"Account no longer exists."});const token=issueSession(u,"qr",req,{totpVerified:p.totp_verified});const done=db.prepare("UPDATE pairings SET state='completed' WHERE id_hash=? AND state='approved'").run(p.id_hash);if(!done.changes){db.prepare("DELETE FROM sessions WHERE token_hash=?").run(hash(token));return res.status(409).json({error:"This code was already used."});}recordSecurityEvent(u.id,"phone_qr_sign_in");res.json({token,user:{name:u.name,phone:u.phone},isDemo:!!u.is_demo,totpEnabled:!!u.totp_enabled,message:"Phone connected."});});
app.post("/api/qr/web/create",async(req,res)=>{if(!rateLimit("qrweb:"+req.ip,15,60000))return tooMany(req,res);if(!/^[a-f0-9]{64}$/i.test(String(req.body?.verifierHash||"")))return res.status(400).json({error:"Browser verifier is invalid."});const p=pairingCreate("web",{verifierHash:req.body.verifierHash}),base=lanBase(req),payload=JSON.stringify({baseUrl:base,codeId:p.raw,flow:"web"});res.json({codeId:p.raw,shortCode:p.shortCode,matchCode:db.prepare("SELECT match_code FROM pairings WHERE id_hash=?").get(hash(p.raw)).match_code,expiresAt:p.expiresAt,backendAddress:base,payload,qrDataUrl:await QRCode.toDataURL(payload,{errorCorrectionLevel:"M",margin:4,width:220})});});
app.post("/api/qr/web/cancel",(req,res)=>{const p=pairingBy(req.body?.codeId,"web"),verifier=String(req.body?.verifier||"");if(!p||!verifier||!safeEq(hash(verifier),p.verifier_hash))return res.status(404).json({error:"Sign-in request is no longer available."});if(["pending","scanned","approved"].includes(p.state))db.prepare("UPDATE pairings SET state='expired' WHERE id_hash=? AND state IN ('pending','scanned','approved')").run(p.id_hash);res.json({ok:true});});
app.post("/api/qr/web/scan",requireUser,(req,res)=>{if(!rateLimit("scan:"+req.user.id,10,60000))return tooMany(req,res);const p=pairingBy(req.body?.codeId,"web");if(!p||pairingState(p)!=="pending")return res.status(410).json({error:"This code expired or was already used."});const changed=db.prepare("UPDATE pairings SET state='scanned',device_user_id=?,device_name=?,address=? WHERE id_hash=? AND state='pending'").run(req.user.id,String(req.body?.deviceName||"Phone").slice(0,80),req.ip,p.id_hash);if(!changed.changes)return res.status(409).json({error:"This code was already used."});res.json({state:"scanned",browser:"Web browser",address:p.address||"Computer on this network",expiresAt:p.expires_at});});
app.post("/api/qr/web/approve",requireUser,(req,res)=>{if(req.user.totp_enabled&&!req.user.totp_verified)return res.status(403).json({error:"Re-authenticate with your authenticator code before approving.",totpRequired:true});const p=pairingBy(req.body?.codeId,"web");if(!p||pairingState(p)!=="scanned"||p.device_user_id!==req.user.id)return res.status(404).json({error:"Sign-in request is no longer available."});const check=attemptPairing(p,req.body?.matchCode);if(!check.ok)return res.status(401).json({error:check.attemptsLeft?("That number did not match. "+check.attemptsLeft+" tries left."):"Too many tries. Start again.",attemptsLeft:check.attemptsLeft});const changed=db.prepare("UPDATE pairings SET state='approved',totp_verified=? WHERE id_hash=? AND state='scanned'").run(req.user.totp_verified?1:0,p.id_hash);if(!changed.changes)return res.status(409).json({error:"This request was already handled."});recordSecurityEvent(req.user.id,"web_qr_approved");res.json({ok:true});});
app.post("/api/qr/web/deny",requireUser,(req,res)=>{const p=pairingBy(req.body?.codeId,"web");if(!p||p.device_user_id!==req.user.id)return res.status(404).json({error:"Sign-in request is no longer available."});db.prepare("UPDATE pairings SET state='denied' WHERE id_hash=? AND state='scanned'").run(p.id_hash);res.json({ok:true});});
app.get("/api/qr/web/status",(req,res)=>{const p=pairingBy(req.query.codeId,"web"),v=String(req.query.verifier||"");if(!p||!safeEq(hash(v),p.verifier_hash))return res.status(401).json({error:"Browser verifier did not match."});res.json({state:pairingState(p),expiresAt:p.expires_at});});
app.post("/api/qr/web/redeem",(req,res)=>{if(!rateLimit("redeem:"+req.ip,10,60000))return tooMany(req,res);const p=pairingBy(req.body?.codeId,"web");if(!p||pairingState(p)!=="approved"||!req.body?.verifier||!safeEq(hash(req.body.verifier),p.verifier_hash))return res.status(401).json({error:"This sign-in request is not approved."});const u=db.prepare("SELECT * FROM users WHERE id=?").get(p.device_user_id);if(!u)return res.status(401).json({error:"Account no longer exists."});const token=issueSession(u,"qr",req,{totpVerified:p.totp_verified,web:true});if(!db.prepare("UPDATE pairings SET state='completed' WHERE id_hash=? AND state='approved'").run(p.id_hash).changes){db.prepare("DELETE FROM sessions WHERE token_hash=?").run(hash(token));return res.status(409).json({error:"This code was already used."});}recordSecurityEvent(u.id,"web_qr_sign_in");setAuthCookies(res,token,"qr",req,true,!!u.is_demo);res.json({...clientSession(req,token),user:{name:u.name,phone:u.phone},isDemo:!!u.is_demo,totpEnabled:!!u.totp_enabled,message:"Signed in as "+u.name});});
// Purge dead rows: expired pairings and expired sessions (startup + periodic).
const purgeExpired=()=>{const t=now();db.prepare("DELETE FROM pairings WHERE expires_at<?").run(t);db.prepare("DELETE FROM sessions WHERE expires_at<=? OR (idle_timeout_minutes IS NOT NULL AND CAST(strftime('%s',COALESCE(last_seen_at,created_at)) AS INTEGER)+idle_timeout_minutes*60<=CAST(strftime('%s',?) AS INTEGER))").run(t,t);db.prepare("DELETE FROM login_failures WHERE failed_at<=?").run(new Date(Date.now()-LOGIN_FAILURE_WINDOW_MS).toISOString());db.prepare("DELETE FROM login_lockouts WHERE locked_until<=?").run(t);};
purgeExpired();setInterval(purgeExpired,15*60000).unref();
app.use(express.static(path.resolve(root,"../public")));
if(db.prepare("SELECT COUNT(*) AS n FROM readings WHERE user_id IS NULL").get().n===0){const seed=db.prepare("INSERT INTO readings(user_id,temperature,humidity,created_at,synthetic) VALUES(NULL,?,?,?,1)");for(let i=24;i>=0;i--)seed.run(18+Math.sin(i/3)*2,61+Math.cos(i/4)*5,new Date(Date.now()-i*3600000).toISOString());}
app.get("/api/events",(req,res)=>{const user=currentUser(req);if((req.get("authorization")||req.get("cookie"))&&!user)return res.sendStatus(401);res.setHeader("Content-Type","text/event-stream");res.setHeader("Cache-Control","no-cache, no-transform");res.setHeader("Connection","keep-alive");res.setHeader("X-Accel-Buffering","no");res.flushHeaders?.();const client={userId:user?.id??null,tokenHash:user?.token_hash??null,res,timer:null};eventClients.add(client);res.write("event: connected\ndata: {}\n\n");client.timer=setInterval(()=>{if(client.tokenHash&&!sessionActive(client.tokenHash)){clearInterval(client.timer);eventClients.delete(client);res.end();return;}res.write(": ping\n\n");},20000);req.on("close",()=>{clearInterval(client.timer);eventClients.delete(client);});});
const port=Number(process.env.PORT||3000),host=process.env.HOST||"127.0.0.1",server=app.listen(port,host);
if(host==="127.0.0.1"&&process.env.PEO_YAME_LAN_HOST&&process.env.PEO_YAME_LAN_HOST!==host){const lanServer=app.listen(port,process.env.PEO_YAME_LAN_HOST);lanServer.on("error",error=>{console.error("Could not bind the Peo Yame LAN listener:",error);server.close(()=>process.exit(1));});}
